const COLORS = ['#FF6B2C','#52A8FF','#34D399','#C084FC','#F472B6','#FBBF24'];
const SAMPLES = [
  { id:'1HSG', name:'HIV-1 protease', note:'Chains A, B · inhibitor MK1' },
  { id:'3PTB', name:'Trypsin', note:'Chain A · benzamidine' },
  { id:'1STP', name:'Streptavidin', note:'Chain A · biotin' }
];
const HYD = new Set(['ALA','VAL','LEU','ILE','MET','PHE','TRP','PRO','CYS']);
const POS = new Set(['ARG','LYS','HIS']);
const NEG = new Set(['ASP','GLU']);
const CAT = { hyd:['Hydrophobic','#FBBF24'], polar:['Polar','#34D399'], pos:['Positive','#52A8FF'], neg:['Negative','#FF5A5F'] };
const catOf = r => HYD.has(r) ? 'hyd' : POS.has(r) ? 'pos' : NEG.has(r) ? 'neg' : 'polar';
const LS = {
  get(k, d){ if (k === 'pocketscan-pro') { try { return sessionStorage.getItem('pocketscan-demo-pro') === 'true'; } catch(e){ return this.pro || false; } } try { const v = localStorage.getItem(k); return v == null ? d : JSON.parse(v); } catch(e){ return d; } },
  set(k, v){ if (k === 'pocketscan-pro') { this.pro = v; try { sessionStorage.setItem('pocketscan-demo-pro', String(v)); } catch(e){} return true; } try { localStorage.setItem(k, JSON.stringify(v)); return true; } catch(e){ return false; } },
  del(k){ try { localStorage.removeItem(k); } catch(e){} }
};
const rng = seed => () => { seed |= 0; seed = seed + 0x6D2B79F5 | 0; let t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };
const d2 = (a, b) => (a.x-b.x)**2 + (a.y-b.y)**2 + (a.z-b.z)**2;
const f3 = n => n.toFixed(3);

function parsePDB(text){
  const atoms = [];
  for (const line of text.split(/\r?\n/)) {
    if (line.startsWith('ENDMDL')) break;
    const rec = line.slice(0,6).trim();
    if (rec !== 'ATOM' && rec !== 'HETATM') continue;
    const x = parseFloat(line.slice(30,38)), y = parseFloat(line.slice(38,46)), z = parseFloat(line.slice(46,54));
    if (!isFinite(x) || !isFinite(y) || !isFinite(z)) continue;
    atoms.push({ serial:parseInt(line.slice(6,11)), name:line.slice(12,16).trim(), resn:line.slice(17,20).trim(), chain:line.slice(21,22).trim() || 'A',
      resi:parseInt(line.slice(22,26)), x, y, z, het: rec === 'HETATM' });
  }
  const prot = atoms.filter(a => !a.het);
  const res = new Set(prot.map(a => a.chain + a.resi));
  const chains = [...new Set(prot.map(a => a.chain))];
  const groups = {};
  atoms.filter(a => a.het && a.resn !== 'HOH' && a.resn !== 'WAT').forEach(a => { const k = a.resn + a.chain + a.resi; (groups[k] = groups[k] || []).push(a); });
  const ligands = Object.values(groups).filter(g => g.length >= 6).map(g => ({ resn:g[0].resn, atoms:g }));
  return { atoms, prot, residues:res.size, chains, ligands };
}

function findPockets(P, seedStr){
  const prot = P.prot;
  if (prot.length < 30) return [];
  let seed = 7; for (const ch of seedStr) seed = (seed * 31 + ch.charCodeAt(0)) | 0;
  const R = rng(seed);
  const C = prot.reduce((s, a) => ({ x:s.x+a.x, y:s.y+a.y, z:s.z+a.z }), { x:0, y:0, z:0 });
  C.x /= prot.length; C.y /= prot.length; C.z /= prot.length;
  const maxD = Math.sqrt(Math.max(...prot.map(a => d2(a, C))));
  const centers = [];
  P.ligands.slice(0,2).forEach(l => {
    const c = l.atoms.reduce((s, a) => ({ x:s.x+a.x, y:s.y+a.y, z:s.z+a.z }), { x:0, y:0, z:0 });
    centers.push({ x:c.x/l.atoms.length, y:c.y/l.atoms.length, z:c.z/l.atoms.length, lig:l.resn });
  });
  const cands = prot.filter(a => a.name === 'CA').filter(a => { const d = Math.sqrt(d2(a, C)); return d > maxD*0.4 && d < maxD*0.8; });
  const inward = a => { const d = Math.sqrt(d2(a, C)) || 1, k = 3 / d; return { x:a.x + (C.x-a.x)*k, y:a.y + (C.y-a.y)*k, z:a.z + (C.z-a.z)*k }; };
  if (!centers.length && cands.length) centers.push(inward(cands[Math.floor(R()*cands.length)]));
  while (centers.length < 6 && cands.length) {
    let best = null, bd = -1;
    for (const a of cands) { const m = Math.min(...centers.map(c => d2(a, c))); if (m > bd) { bd = m; best = a; } }
    if (!best || bd < 64) break;
    centers.push(inward(best));
  }
  const pockets = centers.map(c => {
    const near = prot.filter(a => d2(a, c) < 64);
    const lining = prot.filter(a => d2(a, c) < 42.25);
    const resMap = {};
    lining.forEach(a => { const k = a.chain + a.resi; const dd = d2(a, c); if (!resMap[k] || dd < resMap[k].d) resMap[k] = { resn:a.resn, resi:a.resi, chain:a.chain, d:dd }; });
    const residues = Object.values(resMap).sort((a, b) => a.d - b.d).slice(0,16);
    const hyd = residues.length ? residues.filter(r => HYD.has(r.resn)).length / residues.length : 0;
    const volume = 210 + near.length * 3.3 + (c.lig ? 140 : 0) + R()*60;
    const drug = Math.max(0.05, Math.min(0.96, 0.16 + 0.62*hyd + (c.lig ? 0.14 : 0) + (R()-0.5)*0.1));
    const score = Math.max(0.05, Math.min(0.98, 0.22*drug + 0.34*Math.min(1, near.length/150) + (c.lig ? 0.3 : 0.08) + R()*0.08));
    const nSph = Math.max(8, Math.round(volume / 24));
    const rad = Math.cbrt(volume) * 0.42;
    const spheres = Array.from({ length:nSph }, () => {
      const u = R()*2 - 1, t = R()*Math.PI*2, s = Math.sqrt(1 - u*u), rr = rad * Math.cbrt(R());
      return { x:c.x + rr*s*Math.cos(t), y:c.y + rr*s*Math.sin(t), z:c.z + rr*u, r:0.9 + R()*0.8 };
    });
    return { center:c, lig:c.lig, residues, lining:lining.map(a => a.serial), hyd, pol:1-hyd, volume, drug, score, spheres, radius:rad };
  }).filter(p => p.residues.length >= 4);
  pockets.sort((a, b) => b.score - a.score);
  pockets.forEach((p, i) => { p.rank = i + 1; p.id = 'P' + (i + 1); p.color = COLORS[i % COLORS.length]; });
  return pockets;
}

const ago = t => { const s = Math.round((Date.now() - t) / 1000); if (s < 60) return 'just now'; if (s < 3600) return Math.floor(s/60) + 'm ago'; if (s < 86400) return Math.floor(s/3600) + 'h ago'; return Math.floor(s/86400) + 'd ago'; };
const pad = (s, n, left) => { s = String(s); return left ? s.padStart(n) : s.padEnd(n); };

class Component extends DCLogic {
  state = {
    route: this.props.startRoute ?? 'landing', pro: LS.get('pocketscan-pro', false), history: LS.get('pocketscan-history', []),
    phase:'idle', scan:null, scanName:'', log:[], slow:false, errorMsg:'', selIdx:0, compare:[], compareOpen:false, tab:'residues',
    fileError:'', drag:false, checkout:this.props.checkout === 'success' && !LS.get('pocketscan-pro', false) ? 'open' : (this.props.checkout ?? null), shortcutsOpen:false, toast:'', spin:false,
    heroLoading:true, heroStatus:'Loading structure…', heroCaption:'Pocket 1'
  };
  cache = {};
  timers = [];

  componentDidMount(){
    this.onKey = e => this.handleKey(e);
    window.addEventListener('keydown', this.onKey);
    this.onResize = () => { this.viewer && this.viewer.resize(); this.hero && this.hero.resize(); };
    window.addEventListener('resize', this.onResize);
  }
  componentWillUnmount(){
    window.removeEventListener('keydown', this.onKey); window.removeEventListener('resize', this.onResize);
    this.clearTimers(); clearTimeout(this.toastT); this.hero?.spin(false); this.viewer?.spin(false);
  }
  componentDidUpdate(){
    const s = this.state, p = this._prev || {};
    if (s.scan !== p.scan || s.selIdx !== p.selIdx || s.compare !== p.compare || s.pro !== p.pro) this.draw(s.scan !== p.scan);
    this._prev = { scan:s.scan, selIdx:s.selIdx, compare:s.compare, pro:s.pro };
  }
  clearTimers(){ this.timers.forEach(clearTimeout); this.timers = []; }
  later(fn, ms){ this.timers.push(setTimeout(fn, ms)); }
  notify(msg){ clearTimeout(this.toastT); this.setState({ toast:msg }); this.toastT = setTimeout(() => this.setState({ toast:'' }), 2200); }
  whenLib(cb, tries = 0){
    if (window.$3Dmol) return cb();
    if (tries > 100) return this.setState({ heroStatus:'3D viewer unavailable' });
    setTimeout(() => this.whenLib(cb, tries + 1), 100);
  }
  async fetchSample(id){
    if (this.cache[id]) return this.cache[id];
    const r = await fetch('/structures/' + id + '.pdb');
    if (!r.ok) throw new Error('fetch');
    const t = await r.text();
    this.cache[id] = t;
    return t;
  }

  heroRef = el => {
    if (!el) { this.hero?.spin(false); this.hero?.clear(); this.hero = null; this.heroEl = null; return; }
    if (el === this.heroEl) return;
    this.heroEl = el;
    this.whenLib(async () => {
      try {
        const text = await this.fetchSample('1HSG');
        if (this.heroEl !== el) return;
        const P = parsePDB(text), pk = findPockets(P, '1HSG');
        const v = window.$3Dmol.createViewer(el, { backgroundColor:'#050505', antialias:true });
        this.hero = v;
        v.addModel(text, 'pdb');
        v.setStyle({}, { cartoon:{ color:'#4a4a4a' } });
        v.setStyle({ hetflag:true }, { stick:{ colorscheme:'grayCarbon', radius:0.16 } });
        v.setStyle({ resn:['HOH','WAT'] }, {});
        pk.forEach((p, i) => p.spheres.forEach(s => v.addSphere({ center:s, radius:s.r, color: i === 0 ? '#FF6B2C' : '#666', alpha: i === 0 ? 0.75 : 0.12 })));
        if (pk[0]) v.setStyle({ serial:pk[0].lining }, { cartoon:{ color:'#4a4a4a' }, stick:{ color:'#FF6B2C', radius:0.12 } });
        v.zoomTo(); v.zoom(1.15); v.render(); v.spin('y', 0.35);
        this.setState({ heroLoading:false, heroCaption: pk[0] ? 'Pocket 1 · druggability ' + pk[0].drug.toFixed(2) : 'No pockets' });
      } catch (e) { this.setState({ heroStatus:'Could not load 1HSG from the Protein Data Bank' }); }
    });
  };

  appViewerRef = el => {
    if (!el) { this.viewer?.spin(false); this.viewer?.clear(); this.viewer = null; this.vEl = null; this.drawnId = null; return; }
    if (el === this.vEl) return;
    this.vEl = el;
    this.whenLib(() => {
      if (this.vEl !== el) return;
      this.viewer = window.$3Dmol.createViewer(el, { backgroundColor:'#050505', antialias:true });
      this.draw(true);
    });
  };
  fileInputRef = el => { this.fileInput = el; };

  draw(newScan){
    const v = this.viewer, s = this.state.scan;
    if (!v || !s) return;
    if (this.drawnId !== s.id) { v.clear(); v.addModel(s.text, 'pdb'); this.drawnId = s.id; newScan = true; }
    const st = this.state, comp = new Set(st.compare);
    v.setStyle({}, { cartoon:{ color:'#4a4a4a' } });
    v.setStyle({ hetflag:true }, { stick:{ colorscheme:'grayCarbon', radius:0.16 } });
    v.setStyle({ resn:['HOH','WAT'] }, {});
    v.removeAllShapes();
    s.pockets.forEach((p, i) => {
      const locked = !st.pro && i > 0, on = i === st.selIdx || comp.has(i);
      p.spheres.forEach(sp => v.addSphere({ center:sp, radius:sp.r, color: locked ? '#555' : p.color, alpha: locked ? 0.1 : on ? 0.85 : 0.28 }));
    });
    const sel = s.pockets[st.selIdx];
    if (sel) v.setStyle({ serial:sel.lining }, { cartoon:{ color:'#4a4a4a' }, stick:{ color:sel.color, radius:0.13 } });
    if (newScan || !sel) v.zoomTo(); else v.zoomTo({ serial:sel.lining }, 500);
    v.render();
  }

  handleKey(e){
    const tag = e.target && e.target.tagName;
    if (tag === 'INPUT' || tag === 'TEXTAREA' || e.metaKey || e.ctrlKey || e.altKey) return;
    const st = this.state, k = e.key;
    if (k === '?') { e.preventDefault(); return this.setState({ shortcutsOpen:!st.shortcutsOpen }); }
    if (k === 'Escape') return this.setState({ shortcutsOpen:false, checkout:null, compareOpen:false });
    if (st.shortcutsOpen || st.checkout) return;
    if (k === 'g') return this.setState({ route:'app' });
    if (st.route !== 'app') return;
    if (k === 'u') return this.fileInput && this.fileInput.click();
    if (st.phase !== 'done' || !st.scan) return;
    const n = st.scan.pockets.length;
    if (k === 'j' || k === 'ArrowDown') { e.preventDefault(); this.select(Math.min(n-1, st.selIdx+1)); }
    else if (k === 'k' || k === 'ArrowUp') { e.preventDefault(); this.select(Math.max(0, st.selIdx-1)); }
    else if (/^[1-9]$/.test(k) && +k <= n) this.select(+k - 1);
    else if (k === 'c') this.toggleCompare(st.selIdx);
    else if (k === 'x') this.openCompare();
    else if (k === 'e') this.exportCsv();
    else if (k === 'r') this.resetView();
    else if (k === 't') this.setState({ tab: st.tab === 'residues' ? 'coords' : 'residues' });
  }

  select(i){
    if (!this.state.pro && i > 0) return this.setState({ checkout:'open' });
    this.setState({ selIdx:i, compareOpen:false });
  }
  toggleCompare(i){
    if (!this.state.pro) return this.setState({ checkout:'open' });
    const c = this.state.compare;
    this.setState({ compare: c.includes(i) ? c.filter(x => x !== i) : c.length >= 3 ? [...c.slice(1), i] : [...c, i] });
  }
  openCompare(){
    if (!this.state.pro) return this.setState({ checkout:'open' });
    if (this.state.compare.length >= 2) this.setState({ compareOpen:true });
    else this.notify('Select two or three pockets with the checkboxes, or press C');
  }
  resetView(){ if (this.viewer) { this.viewer.zoomTo(); this.viewer.render(); } }

  async validateFile(f){
    if (!/\.pdb$/i.test(f.name)) return this.setState({ fileError:'Only .pdb files are accepted.' });
    if (f.size === 0) return this.setState({ fileError:'This file is empty.' });
    if (f.size > 10*1024*1024) return this.setState({ fileError:'This file is larger than 10 MiB.' });
    const text = await f.text();
    if (!/^(ATOM|HETATM)/m.test(text)) return this.setState({ fileError:'No ATOM or HETATM records found.' });
    this.setState({ fileError:'' });
    this.startScan({ name:f.name, text, source:'upload' });
  }
  async runSample(id){
    this.clearTimers();
    this.setState({ route:'app', phase:'loading', scan:null, scanName:id + '.pdb', log:[{ t:'0.0s', text:'Fetching ' + id + ' from the Protein Data Bank' }], slow:false, fileError:'' });
    try {
      const text = await this.fetchSample(id);
      this.startScan({ name:id + '.pdb', text, source:'sample', sampleId:id }, true);
    } catch (e) {
      this.last = () => this.runSample(id);
      this.setState({ phase:'error', errorMsg:"Couldn't reach the Protein Data Bank. Check your connection and try again." });
    }
  }
  startScan(src, keepLog){
    this.clearTimers();
    this.last = () => this.startScan(src);
    const scenario = this.props.scenario ?? 'success';
    const k = scenario === 'slow' ? 4 : 1;
    const P = parsePDB(src.text);
    const base = keepLog ? this.state.log : [];
    this.setState({ route:'app', phase:'loading', scan:null, scanName:src.name, log:base, slow:false, selIdx:0, compare:[], compareOpen:false });
    const steps = [
      [150, 'Parsed ' + P.atoms.length.toLocaleString() + ' atoms · ' + P.residues + ' residues · chains ' + (P.chains.join(', ') || '—')],
      [500, 'Preparing illustrative pocket geometry'],
      [850, 'Placing demo spheres on the surface'],
      [1200, 'Clustering spheres into pockets'],
      [1500, 'Scoring pockets']
    ];
    steps.forEach(([ms, text]) => this.later(() => this.setState(s => ({ log:[...s.log, { t:(ms*k/1000).toFixed(1) + 's', text }] })), ms*k));
    if (scenario === 'slow') this.later(() => this.setState({ slow:true }), 3000);
    this.later(() => {
      if (scenario === 'fail') return this.setState({ phase:'error', slow:false, errorMsg:'The analysis service could not process this structure.' });
      const pockets = scenario === 'empty' ? [] : findPockets(P, src.name);
      if (!pockets.length) return this.setState({ phase:'empty', slow:false });
      const id = Date.now().toString(36);
      const scan = { id, name:src.name, text:src.text, sampleId:src.sampleId, P:{ atoms:P.atoms.length, residues:P.residues, chains:P.chains, ligands:P.ligands.map(l => l.resn) }, pockets };
      const stored = src.sampleId ? true : src.text.length < 1500000 && LS.set('pocketscan-pdb-' + id, src.text);
      const entry = { id, name:src.name, sampleId:src.sampleId || null, stored, pockets:pockets.length, at:Date.now() };
      const cap = this.state.pro ? 200 : 10;
      const history = [entry, ...this.state.history].slice(0, cap);
      LS.set('pocketscan-history', history);
      this.setState({ phase:'done', slow:false, scan, history, activeId:id, tab:'residues' });
    }, 1750*k);
  }
  async openHistory(h){
    let text = null;
    try { text = h.sampleId ? await this.fetchSample(h.sampleId) : LS.get('pocketscan-pdb-' + h.id, null); } catch (e) {}
    if (!text) return this.notify("This file wasn't stored. Upload it again.");
    this.clearTimers();
    const P = parsePDB(text), pockets = findPockets(P, h.name);
    this.setState({ route:'app', phase: pockets.length ? 'done' : 'empty', scanName:h.name, selIdx:0, compare:[], compareOpen:false, activeId:h.id,
      scan: { id:h.id, name:h.name, text, sampleId:h.sampleId, P:{ atoms:P.atoms.length, residues:P.residues, chains:P.chains, ligands:P.ligands.map(l => l.resn) }, pockets } });
  }
  removeHistory(h){
    LS.del('pocketscan-pdb-' + h.id);
    const history = this.state.history.filter(x => x.id !== h.id);
    LS.set('pocketscan-history', history);
    this.setState({ history });
  }
  download(name, text, type){
    const url = URL.createObjectURL(new Blob([text], { type }));
    const a = document.createElement('a'); a.href = url; a.download = name; document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }
  visiblePockets(){ const s = this.state.scan; if (!s) return []; return this.state.pro ? s.pockets : s.pockets.slice(0,1); }
  exportCsv(){
    const s = this.state.scan; if (!s) return;
    const rows = [['rank','pocket','score','druggability','volume_A3','alpha_spheres','hydrophobicity','polarity','center_x','center_y','center_z','residues']];
    this.visiblePockets().forEach(p => rows.push([p.rank, p.id, p.score.toFixed(3), p.drug.toFixed(3), p.volume.toFixed(1), p.spheres.length, p.hyd.toFixed(2), p.pol.toFixed(2), f3(p.center.x), f3(p.center.y), f3(p.center.z), '"' + p.residues.map(r => r.resn + r.resi + r.chain).join(' ') + '"']));
    this.download(s.name.replace(/\.pdb$/i, '') + '_pockets.csv', rows.map(r => r.join(',')).join('\n'), 'text/csv');
    this.notify(this.state.pro ? 'Exported ' + s.pockets.length + ' pockets to CSV' : 'Exported the top pocket to CSV');
  }
  exportPdb(){
    if (!this.state.pro) return this.setState({ checkout:'open' });
    const s = this.state.scan; if (!s) return;
    let n = 1; const out = ['HEADER    POCKETSCAN POCKET SPHERES FOR ' + s.name.toUpperCase(), 'REMARK   1 GENERATED BY POCKETSCAN'];
    s.pockets.forEach(p => p.spheres.forEach(sp => {
      out.push('HETATM' + pad(n++, 5, true) + '  APOL STP C' + pad(p.rank, 4, true) + '    ' + pad(sp.x.toFixed(3), 8, true) + pad(sp.y.toFixed(3), 8, true) + pad(sp.z.toFixed(3), 8, true) + '  1.00' + pad(sp.r.toFixed(2), 6, true) + '          Ve');
    }));
    out.push('END');
    this.download(s.name.replace(/\.pdb$/i, '') + '_pockets.pdb', out.join('\n'), 'chemical/x-pdb');
    this.notify('Exported pocket spheres as PDB');
  }

  renderVals(){
    const st = this.state, s = st.scan;
    const go = r => () => this.setState({ route:r, shortcutsOpen:false });
    const pockets = s ? s.pockets : [];
    const sel = pockets[st.selIdx] || pockets[0];
    const locked = i => !st.pro && i > 0;
    const compSet = new Set(st.compare);
    const cmp = st.compare.map(i => pockets[i]).filter(Boolean);
    const fmtRes = r => r.resn + ' ' + r.resi + ' ' + r.chain;
    let shared = [];
    if (cmp.length >= 2) { const sets = cmp.map(p => new Set(p.residues.map(fmtRes))); shared = [...sets[0]].filter(x => sets.every(z => z.has(x))); }
    const bestIdx = key => { let b = 0; cmp.forEach((p, i) => { if (p[key] > cmp[b][key]) b = i; }); return b; };
    const cmpRow = (label, key, fmt) => { const b = bestIdx(key); return { label, cells: cmp.map((p, i) => ({ v:fmt(p), color: i === b ? '#EDEDED' : '#A1A1A1' })) }; };
    const lockedN = !st.pro ? Math.max(0, pockets.length - 1) : 0;
    const canCompare = st.pro && st.compare.length >= 2;
    const curScenarioLabel = st.pro ? 'Pro' : 'Free';

    return {
      navLinks: [['Product','landing'],['App','app'],['Pricing','pricing'],['Account','account']].map(([label, r]) => ({
        label, onClick: go(r), color: st.route === r ? '#EDEDED' : '#8F8F8F', bg: st.route === r ? '#1A1A1A' : 'transparent' })),
      isLanding: st.route === 'landing', isApp: st.route === 'app', isPricing: st.route === 'pricing', isAccount: st.route === 'account',
      isPro: st.pro, showUpgrade: !st.pro,
      goLanding: go('landing'), goApp: go('app'), goAccount: go('account'),
      tryHero: () => this.runSample('1HSG'),
      heroRef: this.heroRef, heroLoading: st.heroLoading, heroStatus: st.heroStatus, heroCaption: st.heroCaption,
      specRows: [
        { k:'Input', v:'PDB format, first model only, ATOM or HETATM records, up to 10 MiB.' },
        { k:'Method', v:'Demo heuristic for interface exploration. Not fpocket or validated scientific analysis.' },
        { k:'Output', v:'Ranked pockets with score, druggability, volume, lining residues and center coordinates.' },
        { k:'Export', v:'CSV on every plan. PDB with pocket spheres on Pro, ready for PyMOL or ChimeraX.' }
      ],

      fileInputRef: this.fileInputRef,
      dropBorder: st.drag ? '#EDEDED' : 'rgba(255,255,255,.16)', dropBg: st.drag ? '#141414' : '#000',
      dragOver: e => { e.preventDefault(); if (!st.drag) this.setState({ drag:true }); },
      dragLeave: () => this.setState({ drag:false }),
      drop: e => { e.preventDefault(); this.setState({ drag:false }); const f = e.dataTransfer.files[0]; if (f) this.validateFile(f); },
      pickFile: e => { const f = e.target.files[0]; e.target.value = ''; if (f) this.validateFile(f); },
      fileError: st.fileError,
      samples: SAMPLES.map(x => ({ ...x, run: () => this.runSample(x.id) })),
      history: st.history.map(h => ({ name:h.name, meta: h.pockets + ' pockets · ' + ago(h.at), bg: st.activeId === h.id && st.phase === 'done' ? '#1A1A1A' : 'transparent',
        open: () => this.openHistory(h), remove: () => this.removeHistory(h) })),
      historyEmpty: st.history.length === 0, historyCount: String(st.history.length),

      appIdle: st.phase === 'idle', appLoading: st.phase === 'loading', appError: st.phase === 'error', appEmpty: st.phase === 'empty', appDone: st.phase === 'done' && !!s,
      scanName: st.scanName, logLines: st.log, slow: st.slow, errorMsg: st.errorMsg,
      sweep: React.createElement('div', { style:{ width:'35%', height:2, background:'#EDEDED', animation:'psSweep 1s ease-in-out infinite' } }),
      cancel: () => { this.clearTimers(); this.setState({ phase:'idle' }); },
      retry: () => this.last && this.last(),
      reset: () => { this.clearTimers(); this.setState({ phase:'idle', scan:null }); },

      metaLine: s ? ['Demo results', s.sampleId || 'upload', s.P.atoms.toLocaleString() + ' atoms', s.P.residues + ' residues', 'chains ' + s.P.chains.join(', ')].concat(s.P.ligands.length ? ['ligand ' + [...new Set(s.P.ligands)].join(', ')] : []).join(' · ') : '',
      appViewerRef: this.appViewerRef,
      viewerHint: 'drag to rotate · scroll to zoom',
      spinLabel: st.spin ? 'Stop spin' : 'Spin',
      toggleSpin: () => { const on = !st.spin; if (this.viewer) this.viewer.spin(on ? 'y' : false, 0.4); this.setState({ spin:on }); },
      resetView: () => this.resetView(),
      compareLabel: 'Compare' + (st.compare.length ? ' (' + st.compare.length + ')' : ''),
      compareCursor: 'pointer', compareOpacity: canCompare || !st.pro ? 1 : 0.6,
      openCompare: () => this.openCompare(), closeCompare: () => this.setState({ compareOpen:false }),
      exportCsv: () => this.exportCsv(), exportPdb: () => this.exportPdb(),

      pocketCount: String(pockets.length),
      pocketRows: pockets.map((p, i) => {
        const L = locked(i), on = i === st.selIdx, c = compSet.has(i);
        return { id:p.id, color: L ? '#444' : p.color, select: () => this.select(i),
          toggle: e => { e.stopPropagation(); this.toggleCompare(i); },
          chk: c ? '✓' : '', chkBg: c ? p.color : 'transparent', chkBorder: c ? p.color : 'rgba(255,255,255,.2)',
          score: L ? '·.··' : p.score.toFixed(2), scorePct: L ? '0%' : (p.score*100) + '%',
          drug: L ? '·.··' : p.drug.toFixed(2), volume: L ? '···' : Math.round(p.volume).toString(),
          bg: on ? '#141414' : 'transparent', bar: on ? 'inset 2px 0 0 ' + p.color : 'none', opacity: L ? 0.45 : 1 };
      }),
      hasLocked: lockedN > 0, lockedText: lockedN + ' more pocket' + (lockedN === 1 ? '' : 's') + ' on Pro',

      showCompare: st.compareOpen && cmp.length >= 2, showDetail: !(st.compareOpen && cmp.length >= 2),
      compareGrid: '140px repeat(' + cmp.length + ', minmax(0,1fr))',
      compareCols: cmp.map(p => ({ id:p.id, color:p.color })),
      compareRows: cmp.length >= 2 ? [
        cmpRow('Score', 'score', p => p.score.toFixed(2)),
        cmpRow('Druggability', 'drug', p => p.drug.toFixed(2)),
        cmpRow('Volume', 'volume', p => p.volume.toFixed(0) + ' Å³'),
        cmpRow('Alpha spheres', 'nS', p => String(p.spheres.length)),
        cmpRow('Hydrophobicity', 'hyd', p => p.hyd.toFixed(2)),
        cmpRow('Residues', 'nR', p => String(p.residues.length)),
        { label:'Ligand nearby', cells: cmp.map(p => ({ v:p.lig || '—', color:'#A1A1A1' })) }
      ] : [],
      sharedLabel: shared.length ? 'Shared residues (' + shared.length + ')' : 'No residues shared between these pockets',
      sharedResidues: shared,

      detail: sel ? {
        id:sel.id, rank:sel.rank, color:sel.color,
        rankText: 'Rank ' + sel.rank + ' of ' + pockets.length + (sel.lig ? ' · contains ligand ' + sel.lig : ''),
        metrics: [
          { k:'Score', v:sel.score.toFixed(2) }, { k:'Druggability', v:sel.drug.toFixed(2) }, { k:'Volume', v:sel.volume.toFixed(0) + ' Å³' },
          { k:'Alpha spheres', v:String(sel.spheres.length) }, { k:'Hydrophobicity', v:sel.hyd.toFixed(2) }, { k:'Polarity', v:sel.pol.toFixed(2) }
        ],
        residues: sel.residues.map(r => ({ label:fmtRes(r), dot:CAT[catOf(r.resn)][1] })),
        centerText: f3(sel.center.x) + ', ' + f3(sel.center.y) + ', ' + f3(sel.center.z),
        spheres: sel.spheres.slice(0,8).map((sp, i) => ({ n:String(i+1), x:f3(sp.x), y:f3(sp.y), z:f3(sp.z), r:sp.r.toFixed(2) })),
        sphereNote: sel.spheres.length > 8 ? 'Showing 8 of ' + sel.spheres.length + ' alpha spheres. Export PDB for all of them.' : ''
      } : { id:'', rank:'', color:'#444', rankText:'', metrics:[], residues:[], centerText:'', spheres:[], sphereNote:'' },
      residueLegend: Object.values(CAT).map(([label, dot]) => ({ label, dot })),
      tabs: [['residues','Residues'],['coords','Coordinates']].map(([id, label]) => ({ label, onClick: () => this.setState({ tab:id }),
        color: st.tab === id ? '#EDEDED' : '#8F8F8F', bg: st.tab === id ? '#1F1F1F' : 'transparent' })),
      tabResidues: st.tab === 'residues', tabCoords: st.tab === 'coords',
      copyCenter: () => { const t = sel ? f3(sel.center.x) + ' ' + f3(sel.center.y) + ' ' + f3(sel.center.z) : ''; try { navigator.clipboard.writeText(t); } catch (e) {} this.notify('Copied center coordinates'); },

      freeCta: st.pro ? 'Included' : 'Current plan',
      pricingRows: [
        { k:'Pockets per scan', free:'Top pocket', pro:'All pockets' },
        { k:'Residue and coordinate detail', free:'Top pocket', pro:'Every pocket' },
        { k:'Compare pockets', free:'—', pro:'Up to 3 at once' },
        { k:'CSV export', free:'Top pocket', pro:'All pockets' },
        { k:'PDB export with pocket spheres', free:'—', pro:'Included' },
        { k:'Scan history', free:'Last 10', pro:'Last 200' }
      ].map(r => ({ ...r, freeColor: r.free === '—' ? '#666' : '#EDEDED' })),

      planName: curScenarioLabel, planSub: st.pro ? 'Demo Pro · no subscription or charge' : 'Demo access · no payment collected',
      cancelPlan: () => { LS.set('pocketscan-pro', false); this.setState({ pro:false, selIdx:0, compare:[], compareOpen:false }); this.notify('Plan cancelled. You are on Free.'); },
      usage: [
        { k:'Scans this month', v:String(st.history.filter(h => new Date(h.at).getMonth() === new Date().getMonth()).length) },
        { k:'Stored scans', v:String(st.history.length) },
        { k:'History limit', v: st.pro ? '200' : '10' }
      ],
      clearHistory: () => { st.history.forEach(h => LS.del('pocketscan-pdb-' + h.id)); LS.set('pocketscan-history', []); this.setState({ history:[] }); this.notify('History cleared'); },

      checkoutOpen: !!st.checkout,
      checkoutTitle: st.checkout === 'success' ? 'Upgrade complete' : st.checkout === 'cancelled' ? 'Checkout' : 'Upgrade to Pro',
      coPlan: st.checkout === 'open', coSuccess: st.checkout === 'success', coCancelled: st.checkout === 'cancelled',
      openCheckout: () => this.setState({ checkout:'open' }),
      closeCheckout: () => this.setState({ checkout:null }),
      paySuccess: () => { LS.set('pocketscan-pro', true); this.setState({ pro:true, checkout:'success' }); },
      payCancel: () => this.setState({ checkout:'cancelled' }),
      stop: e => e.stopPropagation(),

      shortcutsOpen: st.shortcutsOpen, toggleShortcuts: () => this.setState({ shortcutsOpen:!st.shortcutsOpen }),
      shortcuts: [
        { label:'Next / previous pocket', keys:['J','K'] }, { label:'Jump to pocket', keys:['1','–','9'] },
        { label:'Add pocket to compare', keys:['C'] }, { label:'Open compare', keys:['X'] },
        { label:'Switch residues / coordinates', keys:['T'] }, { label:'Export CSV', keys:['E'] },
        { label:'Upload a file', keys:['U'] }, { label:'Reset 3D view', keys:['R'] },
        { label:'Go to app', keys:['G'] }, { label:'Show shortcuts', keys:['?'] }
      ],
      toast: st.toast
    };
  }
}
